const eDots=Array.from({length:126},(_,i)=>({x:55+(i%18)*25.4,y:69+Math.floor(i/18)*33.5}));
const graphLinks=['M80 170C147 170 139 81 235 81','M80 170C147 170 139 259 235 259','M235 81C330 81 316 130 430 170','M235 259C330 259 316 205 430 170'];
